<?php require_once __DIR__.'/../includes/db.php';require_once __DIR__.'/../includes/functions.php';require_role('admin');$pageTitle='Admin Dashboard | StudentHub';$students=(int)($conn->query('SELECT COUNT(*) n FROM students')->fetch_assoc()['n']??0);$users=(int)($conn->query('SELECT COUNT(*) n FROM users')->fetch_assoc()['n']??0);$events=(int)($conn->query('SELECT COUNT(*) n FROM events')->fetch_assoc()['n']??0);$latest=$conn->query('SELECT name,email,created_at FROM users ORDER BY created_at DESC LIMIT 5');$logs=$conn->query('SELECT action,details,created_at FROM audit_logs ORDER BY id DESC LIMIT 8');require __DIR__.'/../includes/header.php'; ?><span class="eyebrow">Administration</span><h1>Admin dashboard</h1><p class="muted">Overview of the StudentHub demo database.</p><div class="stats section"><article class="card stat"><span class="muted">Users</span><strong><?= $users ?></strong></article><article class="card stat"><span class="muted">Students</span><strong><?= $students ?></strong></article><article class="card stat"><span class="muted">Events</span><strong><?= $events ?></strong></article></div><div class="grid two section"><article class="card"><h2>Management tools</h2><p><a href="../students/">Manage students</a></p><p><a href="../events/manage.php">Manage events</a></p><p><a href="../profile.php">View profile</a></p></article><article class="card"><h2>Latest registrations</h2><?php foreach($latest as $u): ?><p><strong><?= e($u['name']) ?></strong><br><small><?= e($u['email']) ?> · <?= e($u['created_at']) ?></small></p><?php endforeach; ?></article></div><h2>Recent audit log</h2><div class="table-wrap"><table><tr><th>Action</th><th>Details</th><th>Time</th></tr><?php foreach($logs as $l): ?><tr><td><?= e($l['action']) ?></td><td><?= e($l['details']) ?></td><td><?= e($l['created_at']) ?></td></tr><?php endforeach; ?></table></div><?php require __DIR__.'/../includes/footer.php'; ?>
